Ref<Texture2D> EditorIconManager::get_icon(const StringName &icon_name) {
	Ref<AtlasTexture> *existing = singleton->icons.getptr(icon_name);
	if (existing) {
		return *existing;
	}
	Ref<AtlasTexture> icon;
	icon.instantiate();
	icon->set_atlas(singleton->get_editor_theme_icon(icon_name));
	singleton->icons[icon_name] = icon;
	return icon;
}
